initial_condition:
with {
   the SUT containing an initial state
}

test_cases.then:
then {
    the SUT sends a valid Response for the operations:
        Update Context Source Registration With Return with Response Status Code set to 404     and
        Update Context Source Registration With Return with Response reason set to 'Not Found'     and
        Update Context Source Registration With Return with Response Body containing the type 'https://uri.etsi.org/ngsi-ld/errors/ResourceNotFound' and Response Body Title is a string and is not ${EMPTY} and Response Body Detail is a string and is not ${EMPTY} and Response Boty Title is not equal to Response Body Detail
}

test_cases.when:
when {
    the SUT receives a Request from the client containing:
        URL set to '/ngsi-ld/v1/csourceRegistrations/{registration_id}'
        method set to 'PATCH'
        Update Context Source Registration with id set to '${registration_id}' and registration update fragment set to '${fragment_with_id}' and content-type set to 'application/ld+json'
}
